1	"use client";
2	
3	import { useState, useRef } from "react";
4	import Link from "next/link";
5	import { useRouter } from "next/navigation";
6	import styles from "../new.module.css";
7	
8	export default function CreateGroupPage() {
9	  const router = useRouter();
10	  const [name, setName] = useState("");
11	  const [color, setColor] = useState("#0a5c36");
12	  const [logo, setLogo] = useState<File | null>(null);
13	  const [logoPreview, setLogoPreview] = useState<string | null>(null);
14	  const [saving, setSaving] = useState(false);
15	  const [error, setError] = useState<string | null>(null);
16	  const fileRef = useRef<HTMLInputElement>(null);
17	
18	  function pickLogo(e: React.ChangeEvent<HTMLInputElement>) {
19	    const f = e.target.files?.[0] || null;
20	    setLogo(f);
21	    setLogoPreview(f ? URL.createObjectURL(f) : null);
22	  }
23	
24	  async function submit(e: React.FormEvent) {
25	    e.preventDefault();
26	    if (!name.trim() || saving) return;
27	    setSaving(true);
28	    setError(null);
29	    try {
30	      const res = await fetch("/api/v2/orgs", {
31	        method: "POST",
32	        headers: { "Content-Type": "application/json" },
33	        body: JSON.stringify({ name: name.trim(), primary_color: color }),
34	      });
35	      const data = await res.json();
36	      if (!res.ok) {
37	        setError(data.error || "Could not create group");
38	        setSaving(false);
39	        return;
40	      }
41	      // Upload the logo after the org exists so it lands in that org's folder.
42	      if (logo) {
43	        const fd = new FormData();
44	        fd.append("file", logo);
45	        const up = await fetch(`/api/v2/orgs/${data.id}/logo`, {
46	          method: "POST",
47	          body: fd,
48	        });
49	        if (!up.ok) {
50	          const upErr = await up.json().catch(() => ({}));
51	          // Group exists; just surface the logo problem instead of blocking.
52	          setError((upErr.error || "Logo upload failed") + " — you can add it in settings.");
53	        }
54	      }
55	      router.push(`/new/${data.slug}`);
56	    } catch {
57	      setError("Something went wrong");
58	      setSaving(false);
59	    }
60	  }
61	
62	  return (
63	    <div className={styles.page}>
64	      <Link href="/new" className={styles.back}>
65	        <svg width="16" height="16" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden>
66	          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.8} d="M15 19l-7-7 7-7" />
67	        </svg>
68	        All groups
69	      </Link>
70	
71	      <p className={styles.eyebrow}>New group</p>
72	      <h1 className={styles.title}>Create a group</h1>
73	      <p className={styles.lede}>
74	        You&apos;ll be the owner. Everyone else joins by an invite code you share —
75	        there&apos;s no open sign-up to a group.
76	      </p>
77	
78	      <form className={styles.form} onSubmit={submit}>
79	        <div className={styles.field}>
80	          <label className={styles.label}>Logo</label>
81	          <div className={styles.logoRow}>
82	            <button
83	              type="button"
84	              className={styles.logoPreview}
85	              onClick={() => fileRef.current?.click()}
86	              aria-label="Choose a logo"
87	              style={
88	                logoPreview
89	                  ? { backgroundImage: `url(${logoPreview})`, backgroundColor: "transparent" }
90	                  : { backgroundColor: color }
91	              }
92	            >
93	              {!logoPreview && (name.charAt(0).toUpperCase() || "?")}
94	            </button>
95	            <div>
96	              <button
97	                type="button"
98	                className={styles.fileBtn}
99	                onClick={() => fileRef.current?.click()}
100	              >
101	                {logo ? "Change logo" : "Choose logo"}
102	              </button>
103	              <p className={styles.swatchHint}>PNG, JPG, WEBP, or SVG (optional)</p>
104	            </div>
105	            <input
106	              ref={fileRef}
107	              type="file"
108	              accept="image/png,image/jpeg,image/webp,image/svg+xml"
109	              onChange={pickLogo}
110	              hidden
111	            />
112	          </div>
113	        </div>
114	
115	        <div className={styles.field}>
116	          <label className={styles.label} htmlFor="group-name">
117	            Group name
118	          </label>
119	          <input
120	            id="group-name"
121	            className={styles.input}
122	            value={name}
123	            onChange={(e) => setName(e.target.value)}
124	            placeholder="e.g. Pine Valley Society"
125	            maxLength={80}
126	            autoFocus
127	          />
128	        </div>
129	
130	        <div className={styles.field}>
131	          <label className={styles.label} htmlFor="group-color">
132	            Brand color
133	          </label>
134	          <div className={styles.colorRow}>
135	            <input
136	              id="group-color"
137	              type="color"
138	              className={styles.swatch}
139	              value={color}
140	              onChange={(e) => setColor(e.target.value)}
141	            />
142	            <span className={styles.swatchHint}>Tints your group&apos;s accents.</span>
143	          </div>
144	        </div>
145	
146	        {error && <p className={styles.formError}>{error}</p>}
147	
148	        <div className={styles.actions}>
149	          <button
150	            type="submit"
151	            className={styles.createBtn}
152	            disabled={!name.trim() || saving}
153	            style={{ opacity: !name.trim() || saving ? 0.6 : 1 }}
154	          >
155	            {saving ? "Creating…" : "Create group"}
156	          </button>
157	          <Link href="/new" className={styles.cancel}>
158	            Cancel
159	          </Link>
160	        </div>
161	      </form>
162	    </div>
163	  );
164	}
