1	"use client";
2	
3	import { useEffect, useState, useCallback } from "react";
4	import Link from "next/link";
5	import ConfirmModal from "../_components/ConfirmModal";
6	import Modal from "../_components/Modal";
7	import styles from "../new.module.css";
8	
9	interface EventRow {
10	  id: string;
11	  name: string;
12	  year: number | null;
13	  start_date: string | null;
14	  end_date: string | null;
15	  status: "draft" | "active" | "archived";
16	  location: string | null;
17	}
18	
19	const empty = { name: "", year: "", start_date: "", end_date: "", status: "draft", location: "" };
20	
21	export default function EventsSection({
22	  orgId,
23	  slug,
24	  isAdmin,
25	}: {
26	  orgId: string;
27	  slug: string;
28	  isAdmin: boolean;
29	}) {
30	  const [events, setEvents] = useState<EventRow[]>([]);
31	  const [editing, setEditing] = useState<EventRow | "new" | null>(null);
32	  const [form, setForm] = useState({ ...empty });
33	  const [busy, setBusy] = useState(false);
34	  const [error, setError] = useState<string | null>(null);
35	  const [confirmDel, setConfirmDel] = useState<EventRow | null>(null);
36	
37	  const fetchEvents = useCallback(async (): Promise<EventRow[]> => {
38	    const r = await fetch(`/api/v2/orgs/${orgId}/events`);
39	    return r.ok ? (await r.json()).events || [] : [];
40	  }, [orgId]);
41	
42	  useEffect(() => {
43	    let active = true;
44	    (async () => {
45	      const e = await fetchEvents();
46	      if (active) setEvents(e);
47	    })();
48	    return () => {
49	      active = false;
50	    };
51	  }, [fetchEvents]);
52	
53	  function openNew() {
54	    setForm({ ...empty });
55	    setError(null);
56	    setEditing("new");
57	  }
58	  function openEdit(e: EventRow) {
59	    setForm({
60	      name: e.name,
61	      year: e.year != null ? String(e.year) : "",
62	      start_date: e.start_date || "",
63	      end_date: e.end_date || "",
64	      status: e.status,
65	      location: e.location || "",
66	    });
67	    setError(null);
68	    setEditing(e);
69	  }
70	
71	  async function save(ev: React.FormEvent) {
72	    ev.preventDefault();
73	    if (!form.name.trim() || busy) return;
74	    setBusy(true);
75	    setError(null);
76	    const payload = {
77	      name: form.name.trim(),
78	      year: form.year ? parseInt(form.year, 10) : null,
79	      start_date: form.start_date || null,
80	      end_date: form.end_date || null,
81	      status: form.status,
82	      location: form.location.trim() || null,
83	    };
84	    const isNew = editing === "new";
85	    const res = await fetch(
86	      isNew ? `/api/v2/orgs/${orgId}/events` : `/api/v2/orgs/${orgId}/events/${(editing as EventRow).id}`,
87	      {
88	        method: isNew ? "POST" : "PATCH",
89	        headers: { "Content-Type": "application/json" },
90	        body: JSON.stringify(payload),
91	      }
92	    );
93	    setBusy(false);
94	    if (!res.ok) {
95	      setError((await res.json().catch(() => ({}))).error || "Could not save");
96	      return;
97	    }
98	    setEditing(null);
99	    setEvents(await fetchEvents());
100	  }
101	
102	  async function remove(id: string) {
103	    await fetch(`/api/v2/orgs/${orgId}/events/${id}`, { method: "DELETE" });
104	    setEvents(await fetchEvents());
105	  }
106	
107	  return (
108	    <div className={styles.section}>
109	      <div className={styles.sectionHead}>
110	        <p className={styles.sectionLabel} style={{ marginBottom: 0 }}>Events</p>
111	        {isAdmin && (
112	          <button type="button" className={styles.circleAddSm} aria-label="New event" onClick={openNew}>
113	            <svg width="13" height="13" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden>
114	              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 5v14M5 12h14" />
115	            </svg>
116	          </button>
117	        )}
118	      </div>
119	
120	      {events.length === 0 ? (
121	        <p className={styles.dnsHint} style={{ marginTop: 0 }}>
122	          {isAdmin ? "No events yet. Tap + to create one." : "No events yet."}
123	        </p>
124	      ) : (
125	        <ul className={styles.memberList}>
126	          {events.map((e) => (
127	            <li key={e.id} className={styles.memberRow}>
128	              <Link
129	                href={`/new/${slug}/admin/events/${e.id}`}
130	                className={styles.memberMeta}
131	                style={{ textDecoration: "none" }}
132	              >
133	                <span className={styles.memberName}>
134	                  {e.name}
135	                  {e.year ? ` (${e.year})` : ""}
136	                </span>
137	              </Link>
138	              <span className={styles.eventStatus}>{e.status}</span>
139	              {isAdmin ? (
140	                <>
141	                  <button type="button" className={styles.removeBtn} onClick={() => openEdit(e)}>
142	                    Edit
143	                  </button>
144	                  <button type="button" className={styles.removeBtn} onClick={() => setConfirmDel(e)}>
145	                    Delete
146	                  </button>
147	                </>
148	              ) : (
149	                <Link href={`/new/${slug}/admin/events/${e.id}`} aria-label={`Open ${e.name}`}>
150	                  <svg className={styles.arrow} width="18" height="18" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden>
151	                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.8} d="M9 5l7 7-7 7" />
152	                  </svg>
153	                </Link>
154	              )}
155	            </li>
156	          ))}
157	        </ul>
158	      )}
159	
160	      <Modal
161	        open={editing !== null}
162	        title={editing === "new" ? "New event" : "Edit event"}
163	        onClose={() => setEditing(null)}
164	      >
165	        <form className={styles.form} onSubmit={save}>
166	          <div className={styles.field}>
167	            <label className={styles.label}>Event name</label>
168	            <input
169	              className={styles.input}
170	              value={form.name}
171	              onChange={(e) => setForm({ ...form, name: e.target.value })}
172	              placeholder="e.g. Golfapalooza XXXI"
173	              maxLength={80}
174	              autoFocus
175	            />
176	          </div>
177	          <div className={styles.field}>
178	            <label className={styles.label}>Year <span className={styles.optional}>(optional)</span></label>
179	            <input
180	              className={styles.input}
181	              inputMode="numeric"
182	              value={form.year}
183	              onChange={(e) => setForm({ ...form, year: e.target.value.replace(/\D/g, "").slice(0, 4) })}
184	              placeholder="2027"
185	            />
186	          </div>
187	          <div className={styles.field}>
188	            <label className={styles.label}>Start date <span className={styles.optional}>(optional)</span></label>
189	            <input className={styles.input} type="date" value={form.start_date}
190	              onChange={(e) => setForm({ ...form, start_date: e.target.value })} />
191	          </div>
192	          <div className={styles.field}>
193	            <label className={styles.label}>End date <span className={styles.optional}>(optional)</span></label>
194	            <input className={styles.input} type="date" value={form.end_date}
195	              onChange={(e) => setForm({ ...form, end_date: e.target.value })} />
196	          </div>
197	          <div className={styles.field}>
198	            <label className={styles.label}>Location <span className={styles.optional}>(optional)</span></label>
199	            <input
200	              className={styles.input}
201	              value={form.location}
202	              onChange={(e) => setForm({ ...form, location: e.target.value })}
203	              placeholder="e.g. Thorn Apple Country Club, Grand Rapids, MI"
204	              maxLength={120}
205	            />
206	          </div>
207	          <div className={styles.field}>
208	            <label className={styles.label}>Status</label>
209	            <select className={styles.roleSelect} value={form.status}
210	              onChange={(e) => setForm({ ...form, status: e.target.value })}>
211	              <option value="draft">draft</option>
212	              <option value="active">active</option>
213	              <option value="archived">archived</option>
214	            </select>
215	          </div>
216	          {form.status === "active" && (
217	            <p className={styles.dnsHint} style={{ marginTop: 0 }}>
218	              Making this active will archive any other active event.
219	            </p>
220	          )}
221	          {error && <p className={styles.formError}>{error}</p>}
222	          <button type="submit" className={styles.createBtn} disabled={busy || !form.name.trim()}>
223	            {busy ? "Saving…" : editing === "new" ? "Create event" : "Save changes"}
224	          </button>
225	        </form>
226	      </Modal>
227	
228	      <ConfirmModal
229	        open={!!confirmDel}
230	        title="Delete event?"
231	        message={confirmDel ? `Delete "${confirmDel.name}"? This can't be undone.` : undefined}
232	        confirmLabel="Delete"
233	        destructive
234	        onConfirm={() => {
235	          const e = confirmDel;
236	          setConfirmDel(null);
237	          if (e) remove(e.id);
238	        }}
239	        onCancel={() => setConfirmDel(null)}
240	      />
241	    </div>
242	  );
243	}
