1	import { NextResponse } from "next/server";
2	import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
3	import { addToAllMembers } from "@/lib/v2/chat/channels";
4	
5	/**
6	 * POST /api/v2/orgs — create a new organization (group).
7	 *
8	 * Any signed-in user may create a group. The creator becomes the sole member,
9	 * as `owner`; everyone else joins only by redeeming an invite (never open join).
10	 *
11	 * Auth accepts a bearer token (native) or the cookie session (web) via
12	 * v2GetUser. Writes use the service role because the first membership can't
13	 * satisfy the membership RLS policy until it exists (chicken-and-egg).
14	 */
15	export async function POST(request: Request) {
16	  const { userId } = await v2GetUser(request);
17	  if (!userId) {
18	    return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
19	  }
20	
21	  let body: { name?: string; primary_color?: string };
22	  try {
23	    body = await request.json();
24	  } catch {
25	    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
26	  }
27	
28	  const name = (body.name || "").trim();
29	  if (!name) {
30	    return NextResponse.json({ error: "Group name is required" }, { status: 400 });
31	  }
32	  if (name.length > 80) {
33	    return NextResponse.json({ error: "Group name is too long" }, { status: 400 });
34	  }
35	  const primaryColor =
36	    typeof body.primary_color === "string" && /^#[0-9a-fA-F]{6}$/.test(body.primary_color)
37	      ? body.primary_color
38	      : "#0a5c36";
39	
40	  const admin = v2AdminClient();
41	
42	  // The creator becomes a member, so they must already have a completed profile
43	  // with a real name (collected at signup). Never mint a nameless member here.
44	  const { data: profile } = await admin
45	    .from("v2_profiles")
46	    .select("first_name, last_name")
47	    .eq("id", userId)
48	    .maybeSingle();
49	  if (!profile || !(profile.first_name || "").trim() || !(profile.last_name || "").trim()) {
50	    return NextResponse.json(
51	      { error: "Add your name before creating a group." },
52	      { status: 400 }
53	    );
54	  }
55	
56	  // Unique slug from the name.
57	  const base =
58	    name
59	      .toLowerCase()
60	      .replace(/[^a-z0-9]+/g, "-")
61	      .replace(/^-+|-+$/g, "")
62	      .slice(0, 40) || "group";
63	  let slug = base;
64	  for (let i = 2; i < 100; i++) {
65	    const { data: existing } = await admin
66	      .from("v2_organizations")
67	      .select("id")
68	      .eq("slug", slug)
69	      .maybeSingle();
70	    if (!existing) break;
71	    slug = `${base}-${i}`;
72	  }
73	
74	  const { data: org, error: orgErr } = await admin
75	    .from("v2_organizations")
76	    .insert({ name, slug, primary_color: primaryColor, created_by: userId })
77	    .select("id, slug")
78	    .single();
79	  if (orgErr || !org) {
80	    return NextResponse.json(
81	      { error: orgErr?.message || "Could not create group" },
82	      { status: 500 }
83	    );
84	  }
85	
86	  const { error: memberErr } = await admin.from("v2_memberships").insert({
87	    org_id: org.id,
88	    user_id: userId,
89	    role: "owner",
90	    status: "active",
91	  });
92	  if (memberErr) {
93	    await admin.from("v2_organizations").delete().eq("id", org.id);
94	    return NextResponse.json({ error: memberErr.message }, { status: 500 });
95	  }
96	
97	  // Seed the org's always-on all-members channel with its creator. Best-effort.
98	  await addToAllMembers(admin, org.id, userId).catch(() => {});
99	
100	  return NextResponse.json({ slug: org.slug, id: org.id });
101	}
