1	import { NextResponse } from "next/server";
2	import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
3	import { isOrgAdmin } from "@/lib/v2/orgs";
4	import { ensureEventRoom } from "@/lib/v2/chat/channels";
5	
6	/**
7	 * Events for an org. GET lists (members); POST creates (admins).
8	 * Only one event may be `active` at a time — activating one archives any other
9	 * active event in the org (a group runs one event at a time).
10	 * Auth: bearer (native) or cookie (web).
11	 */
12	
13	async function guard(request: Request, orgId: string, needAdmin: boolean) {
14	  const { userId } = await v2GetUser(request);
15	  if (!userId) return { error: "Not authenticated", status: 401 as const };
16	  const admin = v2AdminClient();
17	  if (needAdmin && !(await isOrgAdmin(admin, userId, orgId))) {
18	    return { error: "Not allowed", status: 403 as const };
19	  }
20	  return { admin, userId };
21	}
22	
23	const STATUSES = ["draft", "active", "archived"];
24	
25	export async function GET(
26	  request: Request,
27	  { params }: { params: Promise<{ id: string }> }
28	) {
